import{_ as a,o as e,c as r,a as n}from"./chunks/framework.Ld7uezS_.js";const b=JSON.parse('{"title":"2. 消防工作概述","description":"","frontmatter":{},"headers":[],"relativePath":"theory/02-fire-service-overview.md","filePath":"theory/02-fire-service-overview.md","lastUpdated":1787294102000}'),s={name:"theory/02-fire-service-overview.md"};function l(i,t,o,d,h,p){return e(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="_2-消防工作概述" tabindex="-1">2. 消防工作概述 <a class="header-anchor" href="#_2-消防工作概述" aria-label="Permalink to &quot;2. 消防工作概述&quot;">​</a></h1><h2 id="本章学习目标" tabindex="-1">本章学习目标 <a class="header-anchor" href="#本章学习目标" aria-label="Permalink to &quot;本章学习目标&quot;">​</a></h2><p>学完本章，你应该能说清消防工作的方针、原则、单位主体责任，以及消防设施操作员为什么必须“监控—报告—记录”而不能擅自改变系统。</p><h2 id="一、消防工作到底解决什么问题" tabindex="-1">一、消防工作到底解决什么问题 <a class="header-anchor" href="#一、消防工作到底解决什么问题" aria-label="Permalink to &quot;一、消防工作到底解决什么问题&quot;">​</a></h2><p>消防工作不是只在着火后灭火，而是围绕火灾风险建立一套持续工作的防线：预防火灾发生、及时发现异常、控制火势和烟气、保障人员疏散、组织专业救援，并在事后查明原因、整改隐患。</p><p>因此，消防设施操作员的日常值班同样属于消防工作。一个没有及时发现的故障，可能使报警、联动或疏散功能在真正需要时失效。</p><h2 id="二、消防工作方针" tabindex="-1">二、消防工作方针 <a class="header-anchor" href="#二、消防工作方针" aria-label="Permalink to &quot;二、消防工作方针&quot;">​</a></h2><p><strong>预防为主，防消结合。</strong></p><ul><li><strong>预防为主</strong>：把减少火灾发生的可能性放在首位，例如保持疏散通道畅通、及时处理故障、规范用电和动火。</li><li><strong>防消结合</strong>：不能只做日常预防，还要保持报警、灭火、排烟、疏散和救援条件，确保火灾发生后能够及时响应。</li></ul><h2 id="三、消防工作原则" tabindex="-1">三、消防工作原则 <a class="header-anchor" href="#三、消防工作原则" aria-label="Permalink to &quot;三、消防工作原则&quot;">​</a></h2><p><strong>政府统一领导、部门依法监管、单位全面负责、公民积极参与。</strong></p><p>对操作员最重要的是“单位全面负责”：单位要建立制度、配备设施、组织检查和演练，并保证建筑消防设施完好有效。操作员是单位消防安全管理体系中的执行岗位，不等于可以替代单位负责人作出所有管理决定。</p><h2 id="四、单位消防安全职责如何理解" tabindex="-1">四、单位消防安全职责如何理解 <a class="header-anchor" href="#四、单位消防安全职责如何理解" aria-label="Permalink to &quot;四、单位消防安全职责如何理解&quot;">​</a></h2><p>《消防法》第十六条规定的单位职责可以按三个层次理解：</p><ol><li><strong>建制度</strong>：落实责任制，制定消防安全制度和操作规程。</li><li><strong>保设施</strong>：配置设施器材，设置标志，定期检查、维修，保证完好有效。</li><li><strong>保通道</strong>：保持疏散通道、安全出口、消防车通道畅通。</li><li><strong>查隐患</strong>：组织防火检查，及时消除火灾隐患。</li><li><strong>做检测</strong>：对建筑消防设施按规定进行全面检测，保存记录。</li><li><strong>做演练</strong>：组织有针对性的消防演练。</li><li><strong>履行其他法定义务</strong>：执行法律法规规定的其他要求。</li></ol><p>这里的“全面检测”是单位责任，不等于值班员一个人随意拿仪器测量；检测应由符合要求的人员、机构和方案组织实施。</p><h2 id="五、四类主体如何接力完成消防工作" tabindex="-1">五、四类主体如何接力完成消防工作 <a class="header-anchor" href="#五、四类主体如何接力完成消防工作" aria-label="Permalink to &quot;五、四类主体如何接力完成消防工作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主体</th><th>主要作用</th><th>发现设施异常后通常关注什么</th></tr></thead><tbody><tr><td>政府</td><td>统一领导和组织公共消防工作</td><td>公共安全、区域协同和应急资源</td></tr><tr><td>部门</td><td>依法监管本行业或领域</td><td>监管职责、检查和执法边界</td></tr><tr><td>单位</td><td>对本单位消防安全全面负责</td><td>制度、设施、人员、检测、隐患和演练</td></tr><tr><td>公民/员工</td><td>遵守规定、发现并报告火灾风险、参与必要处置</td><td>先保护人员，再报警、疏散和报告</td></tr></tbody></table><p>在岗位现场还要继续分工：操作员负责发现、核实、操作授权范围内的功能和记录；维修/检测人员负责专业判断和技术处理；单位负责人或授权管理人员负责停用、重大风险、资源和整改决策。不是“谁先发现，谁就可以决定所有事情”。</p><h3 id="一条故障责任链" tabindex="-1">一条故障责任链 <a class="header-anchor" href="#一条故障责任链" aria-label="Permalink to &quot;一条故障责任链&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发现异常</span></span>
<span class="line"><span>→ 操作员记录并报告</span></span>
<span class="line"><span>→ 责任人评估影响和临时防护</span></span>
<span class="line"><span>→ 授权维修/检测人员处理</span></span>
<span class="line"><span>→ 复测人员确认结果</span></span>
<span class="line"><span>→ 单位完成恢复、销项和复盘</span></span></code></pre></div><h2 id="五、岗位场景-为什么要记录和报告" tabindex="-1">五、岗位场景：为什么要记录和报告 <a class="header-anchor" href="#五、岗位场景-为什么要记录和报告" aria-label="Permalink to &quot;五、岗位场景：为什么要记录和报告&quot;">​</a></h2><p><strong>场景</strong>：你发现某回路长期故障，主管说“先屏蔽，月底再修”。</p><p>正确处理不是简单拒绝或私自恢复，而是：记录故障位置、时间和影响范围 → 按单位制度报告 → 评估保护范围 → 落实临时防护和告知 → 由授权人员安排维修 → 维修后测试、恢复并留档。</p><h2 id="六、岗位责任边界" tabindex="-1">六、岗位责任边界 <a class="header-anchor" href="#六、岗位责任边界" aria-label="Permalink to &quot;六、岗位责任边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>单位/负责人</th><th>操作员或检测维修人员</th></tr></thead><tbody><tr><td>建立制度、落实责任</td><td>组织建立并监督执行</td><td>按制度和授权执行，发现缺陷报告</td></tr><tr><td>消防设施运行</td><td>保证资金、人员和设施条件</td><td>监视、操作、保养、维修或检测相应项目</td></tr><tr><td>重大停用、改造和风险决策</td><td>组织审批、告知和临时防护</td><td>提供事实记录，不擅自决定重大变更</td></tr><tr><td>事故或火灾处置</td><td>组织预案、外部协同和复盘</td><td>按预案操作、报告、记录并保护自身安全</td></tr></tbody></table><h3 id="三类工作不要混淆" tabindex="-1">三类工作不要混淆 <a class="header-anchor" href="#三类工作不要混淆" aria-label="Permalink to &quot;三类工作不要混淆&quot;">​</a></h3><ul><li><strong>值班监控</strong>：持续观察状态、接收信息、记录和报告；</li><li><strong>维护保养</strong>：保持设备清洁、连接和功能处于规定状态；</li><li><strong>检测维修</strong>：按方案测试、判定、处理故障并复测。</li></ul><p>“看见控制器正常”不能代替全面检测；“做过一次检测”也不能代替持续值班和日常巡查。</p><h2 id="七、自测" tabindex="-1">七、自测 <a class="header-anchor" href="#七、自测" aria-label="Permalink to &quot;七、自测&quot;">​</a></h2><ol><li>“预防为主，防消结合”是方针还是原则？</li><li>单位为什么既要配置消防设施，又要保证其完好有效？</li><li>建筑消防设施全面检测和消防控制室日常监控有什么区别？</li><li>为什么重大停用、改造和联动逻辑变更不能由值班员自行决定？</li></ol><blockquote><p>参考：<a href="https://flk.npc.gov.cn/" target="_blank" rel="noreferrer">《中华人民共和国消防法》</a> 第十六条；<a href="https://xfhyjd.119.gov.cn/zwossread/open1File/FirefightingSkillsAssessmentSystem/2025-11-13/4f0f6d863cf843228b5ce52030b59bb7/16193156145476990d82b-cb9d-43a7-a5f0-522abe3d1f8c%E5%9B%BD%E5%AE%B6%E8%81%8C%E4%B8%9A%E6%8A%80%E8%83%BD%E6%A0%87%E5%87%86%E2%80%94%E2%80%94%E6%B6%88%E9%98%B2%E8%AE%BE%E6%96%BD%E6%93%8D%E4%BD%9C%E5%91%98.pdf" target="_blank" rel="noreferrer">《消防设施操作员国家职业技能标准（2019年版）》</a> 2.2.1。</p></blockquote>`,32)])])}const g=a(s,[["render",l]]);export{b as __pageData,g as default};
